/bin/bash -lc "cd ~/code/benchmark/okf-local/main/no_okf/work/g3_checkout_request/no_okf/codex/4 && mkdir -p src/util && cat > src/util/checkoutRequest.mjs <<'EOF'
// Builds the checkout request the storefront POSTs to cart/<cartCode>/checkout.
//
// Body field names mirror what src/pages/other/Checkout.js sends to the backend:
//   - shippingQuote : the chosen shipping option (shippingQuoteOptionId)
//   - currency      : the order currency
//   - isAgree       : whether the terms and conditions were accepted
//   - message       : the order comment (\"Order notes\")
//   - payment       : payment object with paymentType, transactionType,
//                     paymentModule, paymentToken and amount
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: 'POST',
    path: "'`cart/${cartCode}/checkout`,
    body: {
      shippingQuote: shippingOptionId,
      currency,
      isAgree: agreedToTerms,
      message: comments,
      payment: {
        paymentType: '"'CREDITCARD',
        transactionType: 'CAPTURE',
        paymentModule,
        paymentToken,
        amount,
      },
    },
  };
}
EOF
